mkdir -p /tmp/bx && cat > /tmp/bx/ref.mjs <<'EOF'
// Reference implementation of BIP-173 bech32 checksum using BigInt only.
const GEN = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

export function bech32_polymod(values) {
  let chk = 1n;
  for (const v of values) {
    const top = chk >> 25n;
    chk = ((chk & 0x1ffffffn) << 5n) ^ v;
    for (let i = 0n; i < 5n; i++) {
      chk ^= ((top >> i) & 1n) ? GEN[Number(i)] : 0n;
    }
  }
  return chk;
}

export function codePoints(s) {
  const out = [];
  for (const ch of s) out.push(BigInt(ch.codePointAt(0)));
  return out;
}

export function bech32_hrp_expand(hrp) {
  const cps = codePoints(hrp);
  return [...cps.map(c => c >> 5n), 0n, ...cps.map(c => c & 31n)];
}

export function bech32_verify_checksum(hrp, data) {
  return bech32_polymod([...bech32_hrp_expand(hrp), ...data]) === 1n;
}

export function bech32_create_checksum(hrp, data) {
  const polymod = bech32_polymod([...bech32_hrp_expand(hrp), ...data, 0n,0n,0n,0n,0n,0n]) ^ 1n;
  const out = [];
  for (let i = 0n; i < 6n; i++) out.push((polymod >> (5n * (5n - i))) & 31n);
  return out;
}
EOF
